20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
38	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
39	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
67	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        validateRequiredFields(ownerFieldsDto);
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        rejectDuplicateHousehold(owner, ownerFieldsDto.getSharesHousehold());
122	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
123	        rejectDuplicateTelephone(telephone);
124	        owner.setTelephone(telephone);
125	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
126	        if (owner.getRegistrationDate() == null) {
127	            owner.setRegistrationDate(LocalDate.now());
128	        }
129	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    /**
138	     * Builds the next customer code, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
139	     * upper-cased first three letters of the owner's last name and NNNN is a global 4-digit
140	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
141	     *
142	     * @param lastName the owner's last name
143	     * @return the assigned customer code
144	     */
145	    private String nextCustomerCode(String lastName) {
146	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
147	        int sequence = this.clinicService.findAllOwners().size() + 1;
148	        return String.format("%s-%04d", last3, sequence);
149	    }
150	
151	    /**
152	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
153	     * offending field so the client learns about all of them at once.
154	     *
155	     * @param ownerFieldsDto the submitted owner fields
156	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
157	     *                                     missing or blank
158	     */
159	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
160	        List<String> errors = new ArrayList<>();
161	        if (isBlank(ownerFieldsDto.getFirstName())) {
162	            errors.add("firstName");
163	        }
164	        if (isBlank(ownerFieldsDto.getLastName())) {
165	            errors.add("lastName");
166	        }
167	        if (isBlank(ownerFieldsDto.getAddress())) {
168	            errors.add("address");
169	        }
170	        if (isBlank(ownerFieldsDto.getCity())) {
171	            errors.add("city");
172	        }
173	        if (isBlank(ownerFieldsDto.getTelephone())) {
174	            errors.add("telephone");
175	        }
176	        if (!errors.isEmpty()) {
177	            throw new MissingOwnerFieldsException(errors);
178	        }
179	    }
180	
181	    private boolean isBlank(String value) {
182	        return value == null || value.isBlank();
183	    }
184	
185	    /**
186	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
187	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
188	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
189	     * followed by 8 to 15 digits.
190	     *
191	     * @param telephone the raw telephone value as submitted
192	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
193	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
194	     */
195	    private String normalizeTelephone(String telephone) {
196	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
197	        String nationalSignificantNumber;
198	        if (cleaned.startsWith("+")) {
199	            nationalSignificantNumber = cleaned.substring(1);
200	        } else {
201	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
202	            nationalSignificantNumber = "61" + national;
203	        }
204	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
205	            throw new InvalidTelephoneException(telephone);
206	        }
207	        return "+" + nationalSignificantNumber;
208	    }
209	
210	    /**
211	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
212	     * value is treated as absent and returns {@code null}); when present the value must be a
213	     * syntactically valid address, and is stored and returned lower-cased.
214	     *
215	     * @param email the raw email value as submitted, may be {@code null}
216	     * @return the lower-cased email, or {@code null} when none was supplied
217	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
218	     */
219	    private String normalizeEmail(String email) {
220	        if (email == null || email.isBlank()) {
221	            return null;
222	        }
223	        String normalized = email.trim().toLowerCase();
224	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
225	            throw new InvalidEmailException(email);
226	        }
227	        return normalized;
228	    }
229	
230	    /**
231	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
232	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
233	     * comparison, so numbers that differ only in formatting still count as duplicates.
234	     *
